'use strict';

// MODULES //

var crypto = require( 'crypto' );
var setNonEnumerableReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var format = require( '@stdlib/string/format' );
var generateHMAC = require( './generate_hmac.js' );

// VARIABLES //

var DELIMITER = '<IDS|MSG>';


// MAIN //

/**
* Message constructor.
*
* ## Notes
*
* -   Ref: https://jupyter-client.readthedocs.io/en/latest/messaging.html#general-message-format
*
* @private
* @constructor
* @param {Array<Buffer>} identities - socket identities
* @param {Object} header - message header
* @param {Object} parent_header - parent message header
* @param {Object} metadata - message metadata
* @param {Object} content - message content
* @param {Array<Buffer>} buffers - extras
* @returns {Message} socket instance
*/
function Message( identities, header, parent_header, metadata, content, buffers ) {

	// TODO: IMP, constructor should abstract away uuid, date generation. There is no place where we use it just as an object wrapper (decode handles that).
	// TODO: Just take an object instead, and how to handle automated message creation.
	if ( !( this instanceof Message ) ) {
		return new Message( identities, header, parent_header, metadata, content, buffers );
	}

	// TODO: Do we need more robust validation/defaults and getter/setters?
	// Initialize message properties:
	this.identities = identities || [];
	this.header = header || {};
	this.parent_header = parent_header || {}; // using snake-case to follow jupyter conventions, can be changed if we want it..?
	this.metadata = metadata || {};
	this.content = content || {};
	this.buffers = buffers || [];

	return this;
}

/**
* Decodes raw message frames into a `Message` instance.
*
* @private
* @name decode
* @memberof Message
* @type {Function}
* @param {Array<Buffer>} raw - raw message frames
* @param {string} scheme - signature scheme
* @param {string} key - signature key
* @returns {(Message|TypeError)} message instance
*/
setNonEnumerableReadOnly( Message, 'decode', function decode( raw, scheme, key ) {
	var parent_header;
	var expectedHmac;
	var identities;
	var metadata;
	var content;
	var buffers;
	var header;
	var hmac;
	var i;

	if ( raw.length < 6 ) {
		return new TypeError( format( 'invalid argument. `raw` must have atleast 6 frames. Value: %d', raw.length ) );
	}
	identities = [];
	for ( i = 0; i < raw.length; i++ ) {
		if ( raw[ i ].toString() === DELIMITER ) {
			break;
		}
		identities.push( raw[ i ] );
	}
	if ( raw.length - identities.length < 5 ) {
		return new TypeError( format ( 'invalid argument. `raw` must have atleast 5 frames on top of identity frames. Value: %d', raw.length - identities.length ) );
	}
	hmac = raw[ i + 1 ].toString();
	if ( key !== '' ) {
		expectedHmac = generateHMAC( raw.slice( i+2, i+6 ), scheme, key )
		if ( hmac !== expectedHmac ) {
			return new TypeError( format ( 'invalid message. `raw` must have a valid signature. Value: %s', hmac ) );
		}
	}
	header = JSON.parse( raw[ i + 2 ].toString() );
	parent_header = JSON.parse( raw[ i + 3 ].toString() );
	metadata = JSON.parse( raw[ i + 4 ].toString() );
	content = JSON.parse( raw[ i + 5 ].toString() );
	buffers = raw.slice( i + 6 );

	return new Message( identities, header, parent_header, metadata, content, buffers );
});

/**
* Encodes message into raw frames.
*
* @private
* @name encode
* @memberof Message.prototype
* @type {Function}
* @param {string} scheme - signature scheme
* @param {string} key - signature key
* @returns {Array<Buffer>} raw message frames
*/
setNonEnumerableReadOnly( Message.prototype, 'encode', function encode( scheme, key ) {
	var messageFrames;
	var frames;
	var hmac;

	frames = [];
	frames.push.apply( frames, this.identities );
	frames.push( DELIMITER );

	messageFrames = [
		Buffer.from( JSON.stringify( this.header ) ),
		Buffer.from( JSON.stringify( this.parent_header ) ),
		Buffer.from( JSON.stringify( this.metadata ) ),
		Buffer.from( JSON.stringify( this.content ) ),
	]

	hmac = '';
	if ( key !== '' ) {
		hmac = generateHMAC( messageFrames, scheme, key );
	}
	frames.push( hmac );
	frames.push.apply( frames, [ JSON.stringify( this.header ), JSON.stringify( this.parent_header ), JSON.stringify( this.metadata ), JSON.stringify( this.content ) ] );
	frames.push.apply( frames, this.buffers );

	return frames;
});

/**
* Creates a reply to a message.
*
* @private
* @name createReply
* @memberof Message.prototype
* @type {Function}
* @param {string} type - message type
* @param {Object} content - message contents
* @returns {Message} reply
*/
setNonEnumerableReadOnly( Message.prototype, 'createReply', function createReply( type, content ) {
	var header;

	// TODO: This method should also take in a metadata arg

	header = {
		'msg_id': crypto.randomUUID(),
		'session': this.header.session,
		'username': this.header.username,
		'date': new Date().toISOString(),
		'msg_type': type,
		'version': '5.2'
	}
	return new Message( this.identities, header, this.header, {}, content, [] );
});


// EXPORTS //

module.exports = Message;
